ee:message.ee:set-payload:
%dw 2.0 output application/json
// 1. Resolve Correlation and Business Identifiers safely var resolvedCorrelationId = vars.request.correlationId default vars.command.correlationId default correlationId var resolvedSagaId = vars.request.sagaId default vars.command.sagaId default null var resolvedStepId = vars.request.stepId default vars.command.stepId default null var resolvedStepName = vars.request.stepName default vars.command.stepName default ( if (!isEmpty(vars.requestedSku default '')) 'GET_STOCK' else 'UNKNOWN_STEP' ) var resolvedAttempt = vars.request.attempt default vars.command.attempt default 1
// 2. Classify Failure Type var errorNamespace = error.errorType.namespace default '' var errorIdentifier = error.errorType.identifier default '' var isBusiness = ( (['INVENTORY', 'PAYMENT', 'SHIPPING', 'APIKIT'] contains errorNamespace) or (['UNKNOWN_SKU', 'RESERVATION_NOT_FOUND', 'INSUFFICIENT_STOCK', 'COMMAND_IN_PROGRESS', 'INVALID_COMMAND', 'INVALID_ITEM', 'INVALID_ITEMS', 'INVALID_REQUEST', 'INVALID_QUANTITY', 'PAYMENT_DECLINED', 'PAYMENT_NOT_FOUND', 'INVALID_PAYMENT_STATE', 'SHIPPING_DECLINED', 'SERVICE_UNAVAILABLE', 'SHIPPING_NOT_FOUND', 'INVALID_SHIPPING_STATE', 'STOCK_RESTORE_FAILED', 'RESERVATION_UPDATE_FAILED', 'INVALID_RESERVATION_STATE'] contains errorIdentifier) ) var failureType = if (isBusiness) 'BUSINESS' else 'TECHNICAL'
// 3. Determine Retryability (Only transient technical failures are retryable) var isRetryable = ( (errorNamespace == 'DB' and (['CONNECTIVITY', 'RETRY_EXHAUSTED'] contains errorIdentifier)) or errorIdentifier == 'CONNECTIVITY' or errorNamespace == 'CONNECTIVITY' )
// 4. Determine Standard Failure Code var failureCode = if (errorNamespace == 'APIKIT') ( if (errorIdentifier == 'BAD_REQUEST') 'INVALID_REQUEST' else if (errorIdentifier == 'NOT_FOUND') 'RESOURCE_NOT_FOUND' else if (errorIdentifier == 'METHOD_NOT_ALLOWED') 'METHOD_NOT_ALLOWED' else if (errorIdentifier == 'NOT_ACCEPTABLE') 'NOT_ACCEPTABLE' else if (errorIdentifier == 'UNSUPPORTED_MEDIA_TYPE') 'UNSUPPORTED_MEDIA_TYPE' else if (errorIdentifier == 'NOT_IMPLEMENTED') 'NOT_IMPLEMENTED' else errorIdentifier ) else if (isRetryable) ( if (errorIdentifier == 'RETRY_EXHAUSTED') 'RETRY_EXHAUSTED' else 'CONNECTIVITY_ERROR' ) else ( errorIdentifier default 'INTERNAL_ERROR' )
// 5. Sanitize Failure Message (Never leak SQL syntax, passwords, or card tokens) var rawDescription = error.description default 'An error occurred during transaction processing' var failureMessage = if (isRetryable) 'Transient connectivity failure to database or external service' else if (errorNamespace == 'DB' and !isBusiness) 'A database processing error occurred' else if (errorNamespace == 'APIKIT') ( if (errorIdentifier == 'BAD_REQUEST') 'Malformed JSON request or schema validation constraint violated' else if (errorIdentifier == 'NOT_FOUND') 'Requested API resource not found' else if (errorIdentifier == 'METHOD_NOT_ALLOWED') 'HTTP method not allowed for requested endpoint' else if (errorIdentifier == 'NOT_ACCEPTABLE') 'HTTP accept header not acceptable' else if (errorIdentifier == 'UNSUPPORTED_MEDIA_TYPE') 'Unsupported media type in Content-Type header' else if (errorIdentifier == 'NOT_IMPLEMENTED') 'Feature not implemented' else rawDescription ) else rawDescription
--- { correlationId: resolvedCorrelationId, sagaId: resolvedSagaId, stepId: resolvedStepId, stepName: resolvedStepName, attempt: resolvedAttempt, outcome: 'FAILURE', completedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"}, failureType: failureType, failureCode: failureCode, failureMessage: failureMessage, retryable: isRetryable }
